HIDE_HEAD = ("eval", "document.querySelectorAll('header').forEach(e => { e.style.display = 'none' }); document.querySelectorAll('.sticky').forEach(e => { e.style.position = 'static' })")
UNSTICK = ("eval", "document.querySelectorAll('.sticky').forEach(e => { e.style.position = 'static' })")


def SHOT(who, path, caption, pre=None, hl=None, full=False, el=None, vp=None):
    pre = list(pre or [])
    if el and not full:
        pre.append(HIDE_HEAD)
    elif full:
        pre.append(UNSTICK)
    return _SHOT(who, path, caption, pre=pre or None, hl=hl, full=full, el=el, vp=vp)


